package net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.step;

import java.util.Locale;
import java.util.Optional;
import java.util.Set;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.NewCookie;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallege;
import net.civeira.phylax.features.oauth.authentication.domain.exception.AuthenticationException;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.AuthorizeHtml;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.OidcStep;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.SecureHtmlBuilder;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.StepInput;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.StepOutcome;
import net.civeira.phylax.features.oauth.magiclink.application.usecase.requestmagiclink.RequestMagicLinkUsecase;
import net.civeira.phylax.features.oauth.theme.domain.gateway.DecoratePageGateway;

@ApplicationScoped
@RequiredArgsConstructor
public class MagicLinkStep implements OidcStep {

  private final SecureHtmlBuilder securer;
  private final DecoratePageGateway decorator;
  private final RequestMagicLinkUsecase requestMagicLink;

  @Override
  public AuthenticationChallege challenge() {
    return null;
  }

  @Override
  public Class<? extends AuthenticationException> challengeException() {
    return null;
  }

  @Override
  public Set<String> stepNames() {
    return Set.of("send-magic-link");
  }

  @Override
  public Set<String> initialStepNames() {
    return Set.of("show-magic-link");
  }

  @Override
  public Optional<Response> paintInitial(StepInput input, String error) {
    if (!requestMagicLink.isEnabled(input.tenant())) {
      return Optional.empty();
    }
    return Optional.of(paintAskForm(input, error));
  }

  @Override
  public Response paint(StepInput input, NewCookie preSession) {
    throw new IllegalStateException("MagicLinkStep is not triggered by a challenge exception");
  }

  @Override
  public Optional<StepOutcome> process(StepInput input) {
    if (!"send-magic-link".equals(input.step())) {
      return Optional.empty();
    }
    if (!requestMagicLink.isEnabled(input.tenant())) {
      return Optional.of(new StepOutcome.Render(
          paintAskForm(input, AuthorizeHtml.i18n(input.locale(), "magic-link.ask.disabled"))));
    }

    String email = AuthorizeHtml.first(input.getFormParams(), "email");
    requestMagicLink.request(email, input.getClientDetails().getClientId(),
        input.getRequest().getRedirect().orElse(""), input.tenant(),
        input.getRequest().getScope().orElse(""), input.getRequest().getState().orElse(null),
        input.getRequest().getNonce().orElse(null));

    return Optional.of(new StepOutcome.Render(paintSentForm(input)));
  }

  private Response paintAskForm(StepInput input, String msg) {
    Locale locale = input.locale();
    String js = securer.configureScripts(securer.addSign("sign"), securer.focusOn("email"));
    String title = AuthorizeHtml.i18n(locale, "magic-link.ask.title");
    String help = AuthorizeHtml.i18n(locale, "magic-link.ask.help");
    String label = AuthorizeHtml.i18n(locale, "magic-link.ask.email");
    String send = AuthorizeHtml.i18n(locale, "magic-link.ask.send");
    String backLabel = AuthorizeHtml.i18n(locale, "magic-link.ask.back-label");
    String backText = AuthorizeHtml.i18n(locale, "magic-link.ask.back-text",
        "<input class=\"inline\" type=\"submit\" value=\"" + backLabel + "\" />");
    String error = AuthorizeHtml.i18n(locale, "magic-link.ask.error-format", msg);

    return securer
        .secureHtmlResponse(Response.ok(decorator.getFullPage(input.tenant(), "Magic link",
            js + "<h1>" + title + "</h1>" + "<p>" + help + "</p>"
                + (msg == null ? "" : "<p class=\"error\">" + error + "</p>")
                + "<form method=\"POST\">" + "<input type=\"hidden\" name=\"csid\" id=\"sign\" />"
                + "<input type=\"hidden\" name=\"step\" value=\"send-magic-link\" />" + "<label>"
                + label + " <input type=\"email\" id=\"email\" name=\"email\" value=\"\" /></label>"
                + "<input class=\"primary-button action-button\" type=\"submit\" value=\"" + send
                + "\" />" + "</form>" + "<form method=\"POST\">"
                + "<input type=\"hidden\" name=\"step\" value=\"login\" />" + "<p>" + backText
                + "</p>" + "</form>",
            locale)).type(AuthorizeHtml.TEXT_HTML));
  }

  private Response paintSentForm(StepInput input) {
    Locale locale = input.locale();
    String title = AuthorizeHtml.i18n(locale, "magic-link.sent.title");
    String help = AuthorizeHtml.i18n(locale, "magic-link.sent.help");
    String backLabel = AuthorizeHtml.i18n(locale, "magic-link.sent.back-label");
    String backText = AuthorizeHtml.i18n(locale, "magic-link.sent.back-text",
        "<input class=\"inline\" type=\"submit\" value=\"" + backLabel + "\" />");
    return securer
        .secureHtmlResponse(Response.ok(decorator.getFullPage(input.tenant(), "Magic link",
            "<h1>" + title + "</h1>" + "<p>" + help + "</p>" + "<form method=\"POST\">"
                + "<input type=\"hidden\" name=\"step\" value=\"login\" />" + "<p>" + backText
                + "</p>" + "</form>",
            locale)).type(AuthorizeHtml.TEXT_HTML));
  }
}
